"""Embedded brand assets for Intelbras DVR integration."""
from __future__ import annotations

import base64
import logging
from pathlib import Path

_LOGGER = logging.getLogger(__name__)

ICON_PNG = ''
ICON_2X_PNG = ''
LOGO_PNG = ''
LOGO_2X_PNG = ''

def ensure_brand_assets() -> None:
    """Ensure integration icons and logos exist on disk."""
    try:
        pkg_dir = Path(__file__).resolve().parent
        brand_dir = pkg_dir / "brand"
        brand_dir.mkdir(parents=True, exist_ok=True)

        assets = {
            brand_dir / "icon.png": ICON_PNG,
            brand_dir / "icon@2x.png": ICON_2X_PNG,
            brand_dir / "logo.png": LOGO_PNG,
            brand_dir / "logo@2x.png": LOGO_2X_PNG,
            pkg_dir / "icon.png": ICON_PNG,
            pkg_dir / "logo.png": LOGO_PNG,
        }
        for path, data in assets.items():
            path.write_bytes(base64.b64decode(data))
    except Exception as err:
        _LOGGER.warning("Could not write brand assets: %s", err)
